-- Read-only AZZORA application schema/security fingerprints; no business rows or Auth secrets.
with rows as (
 select 'policies' kind,schemaname||'.'||tablename||'|'||policyname||'|'||permissive||'|'||roles::text||'|'||cmd||'|'||coalesce(qual,'')||'|'||coalesce(with_check,'') value from pg_policies where schemaname='azzora'
 union all select 'relations',n.nspname||'.'||c.relname||'|'||c.relkind::text||'|'||c.relrowsecurity||'|'||c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='azzora' and c.relkind in ('r','p','v')
 union all select 'columns',n.nspname||'.'||c.relname||'|'||a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='azzora' and c.relkind in ('r','p','v') and a.attnum>0 and not a.attisdropped
 union all select 'constraints',n.nspname||'.'||c.relname||'|'||con.conname||'|'||pg_get_constraintdef(con.oid) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='azzora'
 union all select 'indexes',schemaname||'.'||tablename||'|'||indexname||'|'||indexdef from pg_indexes where schemaname='azzora'
 union all select 'functions',n.nspname||'.'||p.proname||'|'||pg_get_function_identity_arguments(p.oid)||'|'||pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='azzora' or (n.nspname='public' and p.proname like 'staging\_%' escape '\')
 union all select 'table_grants',n.nspname||'.'||c.relname||'|'||coalesce(gr.rolname,'PUBLIC')||'|'||acl.privilege_type||'|'||acl.is_grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl left join pg_roles gr on gr.oid=acl.grantee where n.nspname='azzora' and c.relkind in ('r','p','v') and (acl.grantee=0 or gr.rolname in ('anon','authenticated','service_role','azzora_api'))
 union all select 'function_grants',n.nspname||'.'||p.proname||'|'||pg_get_function_identity_arguments(p.oid)||'|'||coalesce(gr.rolname,'PUBLIC')||'|'||acl.privilege_type||'|'||acl.is_grantable from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl left join pg_roles gr on gr.oid=acl.grantee where (n.nspname='azzora' or (n.nspname='public' and p.proname like 'staging\_%' escape '\')) and (acl.grantee=0 or gr.rolname in ('anon','authenticated','service_role','azzora_api'))
 union all select 'schema_grants',n.nspname||'|'||coalesce(gr.rolname,'PUBLIC')||'|'||acl.privilege_type||'|'||acl.is_grantable from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) acl left join pg_roles gr on gr.oid=acl.grantee where n.nspname='azzora' and (acl.grantee=0 or gr.rolname in ('anon','authenticated','service_role','azzora_api'))
)
select kind,count(*) row_count,md5(string_agg(value,E'\n' order by value)) digest from rows group by kind order by kind;

